-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'f4e8895c-3276-423c-803d-0db703356f38';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'The Two Services You Will Actually Use First', 'The existing lessons explain what the cloud is and tour the console. This one puts something in it — a server and a storage bucket, which between them underpin most of what people build on AWS.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'EC2: Renting a Computer by the Hour', 'AWS''s own Back to Basics on deploying code to an EC2 instance — what a virtual server is and how yours comes to exist. Under 6 minutes.', 'https://www.youtube.com/watch?v=f2wvEQ_sWS8', 1,
      array['Explain what an EC2 instance is in plain terms', 'Describe what you choose when launching one — image, size, key pair, security group', 'Say why stopping an instance you are not using matters'],
      'EC2 is a computer you rent by the second. That is genuinely the whole idea. Instead of buying a machine and putting it somewhere with reliable power, you ask AWS for one, it exists a minute later, and you stop paying when you stop it.

WHAT YOU CHOOSE WHEN YOU LAUNCH ONE:

THE AMI (Amazon Machine Image) — the operating system and preinstalled software it starts from. Amazon Linux or Ubuntu for most things.

THE INSTANCE TYPE — how much CPU and memory. `t3.micro` and `t2.micro` are the small ones, and one of them is inside the free tier. Start small; resizing later is easy and cheap, guessing big is neither.

THE KEY PAIR — a file AWS gives you ONCE that lets you log in over SSH. Lose it and you cannot get into that instance again; there is no reset button. Save it somewhere you will still have in six months, and never commit it to a repository.

THE SECURITY GROUP — a firewall. It decides which ports are open and to whom. The default and correct posture is: nothing open except what you need. Opening SSH (port 22) to 0.0.0.0/0 means the entire internet can attempt to log in, and automated scanners will start trying within minutes of the instance existing. Restrict it to your own address where you can.

WHAT NEW USERS GET WRONG, in order of how much it costs them:
- Leaving instances RUNNING. Billing is per second while it runs, whether or not anyone uses it. Stop it when you finish for the day.
- Assuming stopped means free. Stopped compute is free; the attached STORAGE volume still costs a little. Terminate what you are truly done with.
- Choosing a large instance "to be safe".

A REGION NOTE FOR THIS AUDIENCE: pick a region near your users. There is no AWS region in Kenya; the nearest are Cape Town (af-south-1) and the Middle East and European regions. Cape Town is usually the lowest latency for East African users, but check pricing — it differs by region, sometimes noticeably.',
      'Launch one t2.micro or t3.micro instance from the free tier, with a security group that opens SSH only to your own IP address. Connect to it, run one command, and look at the instance''s public IP. Then — and this is the part that matters — STOP it, and check the Instances list until it reads stopped. Set yourself a reminder to go back tomorrow and terminate it.',
      '[{"question":"You lose the key pair file AWS gave you when launching an instance. What happens?","options":["You cannot log into that instance again — there is no reset","AWS emails you a replacement","You can download it again from the console","The instance falls back to password login"],"correct_index":0},{"question":"Why is opening SSH to 0.0.0.0/0 a bad default?","options":["It lets the entire internet attempt to log in, and scanners start within minutes","It slows the instance down","AWS charges extra for open ports","It prevents you from connecting yourself"],"correct_index":0}]'::jsonb),
    (v_m1, 'S3: Storing Files That Never Run Out of Room', 'AWS''s own demo of getting started with Amazon S3 — creating a bucket, putting files in it, and controlling who can read them. Under 8 minutes.', 'https://www.youtube.com/watch?v=FZCZbPEMlXk', 2,
      array['Create a bucket and upload objects to it', 'Explain the difference between object storage and a normal file system', 'Control public access deliberately rather than by accident'],
      'S3 holds files — images, backups, videos, exports — with effectively no size limit, and you pay for what you store and what you transfer out.

OBJECT STORAGE IS NOT A HARD DISK. There are no real folders; a bucket holds objects with keys, and the slashes in `images/2026/photo.jpg` are part of the name rather than a directory tree. You cannot open a file, change three bytes and save — you replace the whole object. That is fine for what S3 is for, and confusing if you expect a drive.

BUCKET NAMES ARE GLOBALLY UNIQUE across all of AWS, which is why every obvious name is taken.

THE PART THAT MATTERS MOST — PUBLIC ACCESS. S3 buckets are private by default, and AWS added Block Public Access after years of leaked buckets exposing real customer data. Leave that block ON unless you have a specific reason. When you do need public files — images for a website — make exactly those objects readable, and never the whole bucket if it also holds anything private. "Public bucket" has been the root cause of a long list of well-publicised data leaks, all of them one setting.

STORAGE CLASSES trade retrieval speed for price: Standard for anything served to users, and cheaper archival tiers for backups you hope never to read. Do not archive anything a page needs to load.

WATCH THE EGRESS. Storing data is cheap. Sending it OUT to the internet is what shows up on the bill — every image view, every download. This is the most common surprise in a first AWS invoice, and it is worth knowing before you host a site''s images there.

AND VERSIONING is worth turning on for anything you care about: it keeps the previous copy when a file is overwritten or deleted, which turns an accidental deletion into an inconvenience rather than a loss.',
      'Create a bucket, upload three files, and confirm with Block Public Access on that the object URL returns Access Denied in a private browser window. Then make ONE object public and check that its URL now loads while the others still do not. Turn versioning on, overwrite a file, and recover the previous version. Delete the bucket when you are done.',
      '[{"question":"Why is S3''s Block Public Access setting so important?","options":["Publicly readable buckets have caused a long list of real data leaks","Public buckets cost more to store","It is required before you can upload files","It speeds up downloads"],"correct_index":0},{"question":"Which S3 cost most often surprises people on a first bill?","options":["Data transferred OUT to the internet, not the storage itself","The cost of creating buckets","A monthly fee per uploaded file","Charges for turning on versioning"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Not Getting Burned: Security and the Bill', 'The two things that actually go wrong for beginners on AWS — assuming Amazon secures everything, and finding out what a month costs after the month.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Who Secures What: the Shared Responsibility Model', 'AWS''s own explanation of the shared responsibility model — the line between what Amazon secures and what remains yours. Under 7 minutes.', 'https://www.youtube.com/watch?v=o13js0hIO_o', 1,
      array['State which security duties belong to AWS and which to you', 'Apply the model to a concrete setup, such as a web server on EC2', 'Stop using the root account for daily work'],
      'The single most expensive misunderstanding in cloud computing is assuming that because Amazon is large and competent, your setup is secure. It is not, and the shared responsibility model is the sentence that explains why.

AWS SECURES THE CLOUD ITSELF: the data centres, the physical machines, the network between them, the hypervisor. You will never patch their hardware or guard their doors.

YOU SECURE WHAT YOU PUT IN IT: your operating system updates, your firewall rules, your passwords and keys, your access permissions, your data and whether it is encrypted, and who can reach what.

SO IN PRACTICE, for a web server on EC2: AWS keeps the physical machine safe. YOU install the operating system updates, choose which ports the security group opens, decide whether the database is reachable from the internet, and control who holds a key. Every breach you read about in cloud infrastructure is on that second list.

THE THINGS TO DO IMMEDIATELY, before anything else in your account:

TURN ON MFA FOR THE ROOT ACCOUNT. Root can do anything, including deleting everything and running up unlimited charges. It is the account most often compromised, and multi-factor authentication is a five-minute job.

STOP USING ROOT FOR DAILY WORK. Create an IAM user for yourself and use that. Root is for a handful of account-level tasks and nothing else.

GRANT THE LEAST ACCESS THAT WORKS. AdministratorAccess on every user is convenient and is how a small mistake becomes a large one.

NEVER PUT ACCESS KEYS IN CODE. Keys committed to a public repository are found by automated scanners within minutes, and the standard outcome is someone mining cryptocurrency on your account and a bill in the thousands of dollars. Use environment variables or, better, IAM roles that hand short-lived credentials to the instance so there is no key to leak. If you ever do expose one, deactivate it immediately and open a support case — AWS has waived fraudulent charges in genuine cases, but never rely on that.',
      'Open your AWS account settings and do three things now: enable MFA on the root user, create an IAM user for your own daily use with only the permissions you need, and check whether any access keys exist that you cannot account for — deactivate those. Then write two lists for something you have built or plan to build: what AWS secures, and what you must.',
      '[{"question":"Under the shared responsibility model, who patches the operating system on your EC2 instance?","options":["You do — AWS secures the infrastructure, you secure what runs on it","AWS, automatically","Nobody; instances do not need patching","It depends on the instance type"],"correct_index":0},{"question":"What is the standard consequence of committing an AWS access key to a public repository?","options":["Scanners find it within minutes and the account is abused, often with a very large bill","AWS rotates the key automatically","Nothing, as long as the repository is deleted afterwards","The key stops working after 24 hours"],"correct_index":0}]'::jsonb),
    (v_m2, 'Controlling the Bill Before It Controls You', 'AWS''s own tutorial on setting up Budgets and billing alerts, so you find out about a cost while you can still stop it. Under 5 minutes.', 'https://www.youtube.com/watch?v=O0sofGVT7uw', 2,
      array['Set a budget and an alert that emails you before spending gets serious', 'Explain what the free tier does and does not cover', 'Find and shut down resources you forgot were running'],
      'AWS bills after the fact. Nothing stops when you hit a number, no card is declined, and the first sign of a problem is an invoice — which is why this is a lesson and not a footnote.

SET A BUDGET TODAY, before you launch anything else. AWS Budgets is free. Set a low monthly amount you would be comfortable paying, and alerts at 50%, 80% and 100% of it. Point the alerts at an email you actually read. This takes five minutes and is the single most valuable thing in this course for anyone learning on their own money.

THE FREE TIER IS NARROWER THAN PEOPLE ASSUME. It covers specific services, in specific sizes, for a limited period — 750 hours a month of a t2.micro or t3.micro for twelve months, a set amount of S3, and so on. It does NOT mean a free account. Run two instances instead of one and the second is billed. Choose a slightly larger instance type and the whole thing is billed. The free tier also expires twelve months after signup, and the bill that follows surprises people every year.

WHERE UNEXPECTED CHARGES USUALLY COME FROM:
- An instance left running in a region you forgot you used. CHECK EVERY REGION — the console shows one at a time, and this catches almost everyone.
- Elastic IP addresses that are reserved but not attached to a running instance; AWS charges precisely to discourage hoarding them.
- Storage volumes and snapshots left behind after an instance was terminated.
- Data transfer out, especially from S3.
- NAT gateways and load balancers, which bill hourly whether or not any traffic passes.

USE COST EXPLORER, which breaks spending down by service and shows what is actually costing money — usually one thing you had forgotten.

AND FOR LEARNING SPECIFICALLY: build it, look at it, then DELETE IT. The habit of tearing down what you built when the lesson ends is what makes it possible to learn AWS on a student budget. In Kenyan shillings, a single forgotten mid-sized instance runs into thousands per month for nothing at all.',
      'Create an AWS Budget with a monthly limit you would genuinely be comfortable paying, and alerts at 50% and 80%, sent to an email you read daily. Then audit your account: switch through every region in the console and look for running instances, unattached Elastic IPs and leftover volumes. Delete what you do not need. Finally open Cost Explorer and identify your single largest cost.',
      '[{"question":"What happens when your AWS spending passes the budget you set?","options":["You get an alert — nothing is stopped automatically, so you must act","AWS suspends the account until you pay","Resources shut down automatically","New launches are blocked"],"correct_index":0},{"question":"Where do forgotten charges most commonly hide?","options":["Resources running in a region you no longer check, since the console shows one region at a time","In the billing dashboard''s tax section","In free-tier services, which bill silently","In the IAM user list"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
